# STAR web prototype: ANOVA for a randomized complete block design, running the recovered STAR R engine.
# The engine sources in ./star are generated by scripts/build_app.R from engine/R.
library(shiny)

for (f in sort(list.files("star", pattern = "[.]R$", full.names = TRUE))) source(f, local = FALSE)

fmt_p <- function(p) ifelse(is.na(p), "", ifelse(p < 0.0001, "<0.0001", formatC(p, format = "f", digits = 4)))
fmt_n <- function(x, digits = 2) ifelse(is.na(x), "", formatC(x, format = "f", digits = digits, big.mark = ","))

anova_display <- function(a) {
  data.frame(Source = a$Source, DF = formatC(a$DF, format = "d"), `Sum of squares` = fmt_n(a$SS),
             `Mean square` = fmt_n(a$MS), `F value` = fmt_n(a$F), `Pr(>F)` = fmt_p(a$P),
             check.names = FALSE, stringsAsFactors = FALSE)
}
means_display <- function(m, trt) {
  out <- data.frame(m$Treatment, fmt_n(m$Mean), formatC(m$N, format = "d"), fmt_n(m$SE), m$Group, stringsAsFactors = FALSE)
  names(out) <- c(trt, "Mean", "N", "SE", "Group")
  out
}
tsv <- function(df) paste(c(paste(names(df), collapse = "\t"), apply(df, 1, paste, collapse = "\t")), collapse = "\n")

copy_js <- "
Shiny.addCustomMessageHandler('copy_text', function(msg) {
  var done = function(ok) { Shiny.setInputValue('copy_status', {ok: ok, what: msg.what, t: Date.now()}); };
  var fallback = function() {
    var ta = document.createElement('textarea'); ta.value = msg.text;
    ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select();
    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta); done(ok);
  };
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(msg.text).then(function() { done(true); }, fallback);
  } else { fallback(); }
});"

ui <- fluidPage(
  tags$head(tags$script(HTML(copy_js)),
            tags$style(HTML(".table { width: auto; min-width: 50%; } .btn { margin: 0 4px 8px 0; }"))),
  titlePanel("STAR (prototype): ANOVA for a randomized complete block design"),
  sidebarLayout(
    sidebarPanel(
      radioButtons("src", "Data", c("Example (rice yield, 6 N levels x 3 reps)" = "ex", "Upload CSV" = "up")),
      conditionalPanel("input.src == 'up'", fileInput("file", "CSV file", accept = ".csv")),
      uiOutput("var_pickers"),
      selectInput("pw", "Mean comparison (letters shown when the effect is significant)",
                  c("Automatic: LSD if <= 5 levels, else Tukey" = "auto", "LSD" = "LSD", "Tukey HSD" = "HSD",
                    "Duncan" = "duncan", "SNK" = "SNK", "Scheffe" = "scheffe")),
      selectInput("alpha", "Significance level", c("0.05" = 0.05, "0.01" = 0.01, "0.10" = 0.10)),
      actionButton("go_aov", "Run ANOVA", class = "btn-primary")
    ),
    mainPanel(
      uiOutput("aov_msg"),
      tabsetPanel(
        tabPanel("Results",
          br(), uiOutput("summary_box"),
          h4("Analysis of variance"),
          actionButton("cp_anova", "Copy table"), tableOutput("anova_tbl"),
          h4("Treatment means"),
          actionButton("cp_means", "Copy table"), tableOutput("means_tbl"),
          br(), downloadButton("dl_xlsx", "Download Excel (.xlsx)")
        ),
        tabPanel("Plot", br(), plotOutput("means_plot", height = "420px"),
                 downloadButton("dl_png", "Download PNG")),
        tabPanel("Classic STAR report", br(),
                 actionButton("cp_report", "Copy report"), downloadButton("dl_txt", "Download TXT"),
                 verbatimTextOutput("report"))
      )
    )
  )
)

server <- function(input, output, session) {
  dat <- reactive({
    if (input$src == "ex") return(read.csv("example_rcbd.csv"))
    req(input$file); read.csv(input$file$datapath)
  })
  output$var_pickers <- renderUI({
    nm <- names(dat())
    tagList(
      selectInput("resp", "Response variable", nm, selected = tail(nm, 1)),
      selectInput("trt", "Treatment factor", nm, selected = nm[min(2, length(nm))]),
      selectInput("blk", "Block / replication", nm, selected = nm[1])
    )
  })

  res <- eventReactive(input$go_aov, {
    req(input$resp, input$trt, input$blk)
    tryCatch(star_aov_rcbd(dat(), input$resp, input$trt, input$blk, test = input$pw, alpha = as.numeric(input$alpha)),
             error = function(e) structure(list(message = conditionMessage(e)), class = "star_error"))
  })
  ok <- reactive({ r <- res(); req(!inherits(r, "star_error")); r })
  output$aov_msg <- renderUI({ r <- res(); if (inherits(r, "star_error")) div(class = "alert alert-danger", r$message) })

  output$summary_box <- renderUI({ r <- ok(); div(class = if (r$significant) "alert alert-success" else "alert alert-info", r$summary) })
  anova_df <- reactive(anova_display(ok()$anova))
  means_df <- reactive(means_display(ok()$means, ok()$treatment))
  output$anova_tbl <- renderTable(anova_df(), align = "lrrrrr")
  output$means_tbl <- renderTable(means_df(), align = "lrrrc")
  output$means_plot <- renderPlot(star_plot_means(ok()))
  output$report <- renderText(paste(ok()$report, collapse = "\n"))

  output$dl_xlsx <- downloadHandler("star_anova_rcbd.xlsx", function(file) {
    r <- ok()
    openxlsx::write.xlsx(list(ANOVA = r$anova, Means = r$means,
                              Info = data.frame(Item = c("Response", "Treatment", "Block", "Mean comparison", "Alpha", "Grand mean", "CV (%)", "Summary"),
                                                Value = c(r$response, r$treatment, r$block, r$test, r$alpha, round(r$grand_mean, 4), round(r$cv, 2), r$summary))),
                         file)
  })
  output$dl_png <- downloadHandler("star_means_plot.png", function(file) {
    png(file, width = 1000, height = 700, res = 120); star_plot_means(ok()); dev.off()
  })
  output$dl_txt <- downloadHandler("star_anova_rcbd_report.txt", function(file) writeLines(ok()$report, file))

  observeEvent(input$cp_anova, session$sendCustomMessage("copy_text", list(what = "ANOVA table", text = tsv(anova_df()))))
  observeEvent(input$cp_means, session$sendCustomMessage("copy_text", list(what = "Means table", text = tsv(means_df()))))
  observeEvent(input$cp_report, session$sendCustomMessage("copy_text", list(what = "Report", text = paste(ok()$report, collapse = "\n"))))
  observeEvent(input$copy_status, {
    st <- input$copy_status
    showNotification(if (isTRUE(st$ok)) paste(st$what, "copied to clipboard") else "Copy failed: select the text and copy manually",
                     type = if (isTRUE(st$ok)) "message" else "error", duration = 3)
  })
}

shinyApp(ui, server)
